yakit.AutoInitYakit()

// 接收项目ID
projectId = cli.Int(
    "project_id",
    cli.setRequired(true),
    cli.setVerboseName("项目ID"),
    cli.setHelp("需要更新的SSA项目ID"),
)

// 使用JSON Schema定义配置数据（匹配 ssaconfig.Config 结构）
configData = cli.Json("config_data",
    cli.setVerboseName("配置数据"),
    cli.setRequired(true),
    cli.setJsonSchema(<<<JSON
{
  "type": "object",
  "properties": {
    "BaseInfo": {
      "title": "基础信息",
      "type": "object",
      "properties": {
        "project_name": {
          "title": "项目名称",
          "type": "string"
        },
        "project_description": {
          "title": "项目描述",
          "type": "string"
        },
        "language": {
          "title": "项目语言",
          "type": "string",
          "enum": ["java", "php", "yak", "js", "ts", "golang", "c"]
        }
      },
      "required": ["project_name", "language"]
    },
    "CodeSource": {
      "title": "代码源配置",
      "type": "object",
      "properties": {
        "kind": {
          "title": "源码类型",
          "type": "string",
          "enum": ["local", "compression", "jar", "git", "svn"]
        },
        "local_file": {
          "title": "本地路径",
          "type": "string",
          "yakit_type": "folder"
        },
        "url": {
          "title": "远程URL",
          "type": "string"
        },
        "branch": {
          "title": "分支",
          "type": "string"
        },
        "path": {
          "title": "子路径",
          "type": "string"
        },
        "auth": {
          "title": "认证配置",
          "type": "object",
          "properties": {
            "kind": {
              "title": "认证方式",
              "type": "string",
              "enum": ["", "password", "ssh_key"],
              "enumNames": ["无需认证", "用户名密码", "SSH密钥"],
              "default": ""
            }
          },
          "dependencies": {
            "kind": {
              "oneOf": [
                {
                  "title": "用户名密码认证",
                  "properties": {
                    "kind": {
                      "enum": ["password"]
                    },
                    "user_name": {
                      "title": "用户名",
                      "type": "string",
                      "description": "Git/SVN 认证用户名"
                    },
                    "password": {
                      "title": "密码/Token",
                      "type": "string",
                      "description": "密码或访问令牌（如GitHub Token）"
                    }
                  },
                  "required": ["user_name", "password"]
                },
                {
                  "title": "SSH密钥认证",
                  "properties": {
                    "kind": {
                      "enum": ["ssh_key"]
                    },
                    "user_name": {
                      "title": "用户名",
                      "type": "string",
                      "description": "Git/SVN 认证用户名（通常为git）",
                      "default": "git"
                    }
                  },
                  "required": ["user_name"],
                  "oneOf": [
                    {
                      "title": "使用本地私钥文件",
                      "properties": {
                        "key_path": {
                          "title": "SSH私钥路径",
                          "type": "string",
                          "yakit_type": "file",
                          "description": "SSH私钥文件路径，例如: ~/.ssh/id_rsa"
                        }
                      },
                      "required": ["key_path"]
                    },
                    {
                      "title": "直接输入私钥内容",
                      "properties": {
                        "key_content": {
                          "title": "SSH私钥内容",
                          "type": "string",
                          "format": "textarea",
                          "description": "直接粘贴SSH私钥内容（PEM格式，包含 BEGIN/END 标记和换行）"
                        }
                      },
                      "required": ["key_content"]
                    }
                  ]
                },
                {
                  "properties": {
                    "kind": {
                      "enum": [""]
                    }
                  }
                }
              ]
            }
          }
        },
        "proxy": {
          "title": "代理配置",
          "type": "object",
          "properties": {
            "url": {
              "title": "代理URL",
              "type": "string",
              "description": "代理服务器地址，例如: http://127.0.0.1:8080"
            },
            "user": {
              "title": "代理用户名",
              "type": "string"
            },
            "password": {
              "title": "代理密码",
              "type": "string"
            }
          }
        }
      }
    },
    "SSACompile": {
      "title": "编译配置",
      "type": "object",
      "properties": {
        "strict_mode": {
          "title": "严格模式",
          "type": "boolean",
          "default": false
        },
        "peephole_size": {
          "title": "窥视孔大小",
          "type": "integer",
          "default": 0,
          "description": "项目分片大小，0表示关闭"
        },
        "exclude_files": {
          "title": "排除文件",
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": ["**/vendor/**,**/classes/**,",  "**/target/**"]
        },
        "re_compile": {
          "title": "重新编译",
          "type": "boolean",
          "default": true
        },
        "memory_compile": {
          "title": "内存编译",
          "type": "boolean",
          "default": false
        },
        "compile_concurrency": {
          "title": "编译并发数",
          "type": "integer",
          "default": 10
        },
        "enable_incremental_compile": {
          "title": "启用增量编译",
          "type": "boolean",
          "default": false,
          "description": "启用增量编译模式。首次编译时作为基础程序；后续编译时基于基础程序进行差量编译，只编译变更的文件，提高编译速度。"
        },
        "base_program_name": {
          "title": "基础程序名称",
          "type": "string",
          "description": "增量编译的基础程序名称。必须已存在于数据库中。如果不提供，当前编译将作为基础程序（首次增量编译）。"
        }
      }
    }
  },
  "required": ["BaseInfo"]
}
JSON
    ),
)

cli.check()
yakit.Code(configData)
yakit.Info("开始更新SSA项目，项目ID: %d", projectId)

yakit.Info("加载项目...")
project, err = ssa.GetSSAProjectByID(projectId)
if err != nil {
    yakit.Error("加载SSA项目失败: %v", err)
    return
}

yakit.Info("成功加载项目: %s (ID: %d)", project.ProjectName, project.ID)

yakit.Info("更新项目配置...")
configBytes, err = json.Marshal(configData)
if err != nil {
    yakit.Error("序列化配置失败: %v", err)
    return
}

err = project.UpdateConfig(ssa.withJsonRawConfig(configBytes))
if err != nil {
    yakit.Error("更新SSA项目配置失败: %v", err)
    return
}
err = project.SaveToDB()
if err != nil {
    yakit.Error("保存SSA项目失败: %v", err)
    return
}
yakit.Info("SSA项目更新成功!")
// 这里返回数据，前端收到会进行前端更新
yakit.Output({
    "success": true,
    "project_id": project.ID,
    "project_name": project.ProjectName,
    "description": project.Description,
    "path":project.URL,
    "language": project.Language,
    "tags": project.Tags,
})
